SELECT   c.id AS "Id do Curso",   c.fullname AS "Nome do Curso",   cc.name AS "Categoria do Curso",   fb.name AS "Nome da Pesquisa",   q.name AS "Pergunta",   COALESCE(CAST(cfd_carga.value AS DECIMAL), 0) AS "Carga Horária",   SUBSTRING_INDEX(     CASE       WHEN q.presentation LIKE 'r>>%' AND a.value REGEXP '^[0-9]+$' THEN TRIM(         SUBSTRING_INDEX(           SUBSTRING_INDEX(             CONCAT(SUBSTRING_INDEX(q.presentation, '>>', -1), '|'),             '|',             (a.value + 1)           ),           '|',           -1         )       )       ELSE IFNULL(a.value, 'Resposta não identificada')     END,     '<<<<<',     1   ) AS "Resposta",    COUNT(*) AS "Qtd por Resposta",   MAX(tr.total_pergunta) AS "Total de Respostas",      ROUND(     100.0 * COUNT(*) / NULLIF(MAX(tr.total_pergunta), 0),     2   ) AS "Distribuição Percentual",    DATE_FORMAT(     FROM_UNIXTIME(MAX(fc.timemodified)),     '%d/%m/%Y %H:%i:%s'   ) AS "Data da Última Resposta"  FROM mdl_feedback fb JOIN mdl_course c ON c.id = fb.course JOIN mdl_course_categories cc ON cc.id = c.category JOIN mdl_feedback_item q ON q.feedback = fb.id  LEFT JOIN mdl_feedback_completed fc ON fc.feedback = fb.id LEFT JOIN mdl_feedback_value a ON a.completed = fc.id AND a.item = q.id  INNER JOIN mdl_customfield_data cfd_obs ON cfd_obs.instanceid = c.id INNER JOIN mdl_customfield_field cff_obs ON cff_obs.id = cfd_obs.fieldid AND cff_obs.shortname = 'obs'  LEFT JOIN mdl_customfield_data cfd_carga ON cfd_carga.instanceid = c.id LEFT JOIN mdl_customfield_field cff_carga ON cff_carga.id = cfd_carga.fieldid AND cff_carga.shortname = 'carga_horaria'  LEFT JOIN (   SELECT     c2.id AS curso_id,     fb2.id AS feedback_id,     q2.id AS pergunta_id,     COUNT(*) AS total_pergunta   FROM mdl_feedback fb2   JOIN mdl_course c2 ON c2.id = fb2.course   JOIN mdl_feedback_item q2 ON q2.feedback = fb2.id   LEFT JOIN mdl_feedback_completed fc2 ON fc2.feedback = fb2.id   LEFT JOIN mdl_feedback_value a2 ON a2.completed = fc2.id AND a2.item = q2.id   INNER JOIN mdl_customfield_data cfd_obs2 ON cfd_obs2.instanceid = c2.id   INNER JOIN mdl_customfield_field cff_obs2 ON cff_obs2.id = cfd_obs2.fieldid AND cff_obs2.shortname = 'obs'   WHERE     fb2.course IS NOT NULL     AND a2.value IS NOT NULL     AND TRIM(a2.value) <> ''     AND (cfd_obs2.value != '0' OR cfd_obs2.value IS NULL)   GROUP BY c2.id, fb2.id, q2.id ) tr ON tr.curso_id = c.id AND tr.feedback_id = fb.id AND tr.pergunta_id = q.id  WHERE   fb.course IS NOT NULL   AND a.value IS NOT NULL   AND TRIM(a.value) <> ''   AND (cfd_obs.value != '0' OR cfd_obs.value IS NULL)   AND q.name <> '6 - O que poderia ser melhorado?'  GROUP BY   c.id,   c.fullname,   cc.name,   fb.name,   q.id,   q.name,   a.value,   q.presentation,   cfd_carga.value,   tr.total_pergunta  ORDER BY   c.fullname,   fb.name,   q.name,   "Resposta";
